import {
  Group, Mesh, PlaneGeometry, BoxGeometry,
  MeshStandardNodeMaterial, MeshBasicNodeMaterial,
  Color, RepeatWrapping, LinearFilter
} from 'three/webgpu';
import {
  float, vec2, vec3, vec4, mix, step, smoothstep,
  time, uniform, uv, texture, positionWorld,
  screenUV, cameraPosition, normalize, dot,
  reflect, pow, length, max, abs, sin, cos,
  Fn, If, Loop, Break, vec2Uniform, rand, hash
} from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const group = new Group();
  const cleanups = [];
  const timelines = [];
  const colors = config.colors || config.intent?.visualSpec?.colors || {};
  const textContent = config.textContent || config.intent?.visualSpec?.textContent || [];
  const effects = config.effects || config.intent?.visualSpec?.effects || '';

  // --- Constants ---
  const plateW = 1.9;
  const plateH = 1.2;
  const pitch = 1.5;
  const numPlates = 6;
  const loopHeight = numPlates * pitch;
  const bevelSize = 0.03;
  const accentWidth = 0.03;
  const colX = 0.9;

  // --- Backdrop (dark gradient + subtle film grain to avoid FLAT_VOID) ---
  const backGeo = new PlaneGeometry(7, 7);
  const backMat = new MeshBasicNodeMaterial();
  const backFn = Fn(() => {
    const vUv = uv();
    const grain = rand(vUv * 100.0 + float(time).mul(0.1)).mul(0.025).add(0.975);
    const c0 = vec3(0.043, 0.043, 0.063); // #0b0b10
    const c1 = vec3(0.078, 0.078, 0.102); // #14141a
    const col = mix(c0, c1, vUv.y).mul(grain);
    return vec4(col, 1.0);
  });
  backMat.colorNode = backFn();
  backMat.depthWrite = false;
  const backdrop = new Mesh(backGeo, backMat);
  backdrop.position.z = -2.5;
  group.add(backdrop);

  // --- Procedural filmic photograph per plate (no blue) ---
  const photoFn = Fn(([seed]) => {
    const vUv = uv();
    const g = hash(vUv * 37.0 + seed).mul(2.0).sub(1.0);
    const noise = sin(vUv.x * 400.0 * seed + vUv.y * 300.0).mul(0.15);
    const base = 0.2 + g.mul(0.15) + noise;
    // Adjust contrast
    const contrast = mix(0.1, 0.5, smoothstep(0.2, 0.8, base));
    // Warm tones (no blue)
    const warm = vec3(0.9, 0.8, 0.7).mul(contrast);
    // Vignette
    const vig = smoothstep(0.5, 0.0, length(vUv.sub(0.5)).mul(1.6));
    const final = mix(vec3(0.08, 0.06, 0.05), warm, vig);
    return vec4(final, 1.0);
  });

  // --- Build plates synchronously ---
  const plates = [];
  const captions = [];

  const headlineItem = textContent.find(t => t.role === 'headline' || t.text === 'Inside the atelier');
  if (headlineItem) {
    const h = ctx.fontAtlas.createText(headlineItem.text, {
      fontSize: 68,
      color: colors.paper || '#e8ecf2',
      align: 'left'
    });
    h.position.set(-1.6, 1.9, 0.1);
    h.scale.set(0.002, 0.002, 0.002);
    group.add(h);
  }

  const captionItems = textContent.filter(t => t.role === 'caption' || (t.typography && t.typography.fontSize <= 24));

  for (let i = 0; i < numPlates; i++) {
    const pg = new Group();
    pg.position.set(colX, -i * pitch, 0);

    // Plate surface
    const pGeo = new PlaneGeometry(plateW, plateH);
    const pMat = new MeshStandardNodeMaterial();
    pMat.roughness = 0.6;
    pMat.metalness = 0.1;
    pMat.clearcoat = 0.1;
    // Assign distinct procedural photograph
    pMat.colorNode = photoFn(float(i));
    const plate = new Mesh(pGeo, pMat);
    pg.add(plate);

    // Bevel frame (ink #16161d)
    const bGeo = new BoxGeometry(plateW + bevelSize * 2, plateH + bevelSize * 2, 0.03);
    const bMat = new MeshStandardNodeMaterial();
    bMat.color = new Color(colors.ink || '#16161d');
    bMat.roughness = 0.5;
    bMat.metalness = 0.5;
    const bevel = new Mesh(bGeo, bMat);
    bevel.position.z = -0.015;
    pg.add(bevel);

    // Accent strip (left edge, red)
    const aGeo = new PlaneGeometry(accentWidth, plateH);
    const aMat = new MeshBasicNodeMaterial();
    aMat.color = new Color(colors.accent || '#ff2a38');
    const accent = new Mesh(aGeo, aMat);
    accent.position.set(-plateW / 2 - bevelSize, 0, 0.015);
    pg.add(accent);

    // Caption (fade up when focused)
    const cap = captionItems[i];
    if (cap) {
      const c = ctx.fontAtlas.createText(cap.text, {
        fontSize: 18,
        color: colors.paper || '#e8ecf2',
        align: 'left',
        letterSpacingPx: 12
      });
      c.position.set(-plateW / 2 - bevelSize - 0.5, 0, 0.02);
      c.scale.set(0.0015, 0.0015, 0.0015);
      c.visible = false;
      pg.add(c);
      captions.push({ mesh: c, plateIdx: i });
    }

    group.add(pg);
    plates.push({
      group: pg,
      plate: plate,
      accent: accent,
      caption: cap ? pg.children[pg.children.length - 1] : null,
      focused: false
    });
  }

  // --- Scroll state & handling ---
  const scrollState = {
    currentY: 0,
    targetY: 0,
    velocity: 0,
    animId: null,
    settling: false
  };

  function updatePlates(y) {
    for (let i = 0; i < numPlates; i++) {
      let py = -i * pitch - y;
      // Wrap into [-loopHeight/2, loopHeight/2]
      while (py < -loopHeight / 2) py += loopHeight;
      while (py > loopHeight / 2) py -= loopHeight;
      plates[i].group.position.y = py;

      const dist = Math.abs(py);
      const focused = dist < pitch / 2;

      if (focused && !plates[i].focused) {
        plates[i].focused = true;
        gsap.to(plates[i].plate.scale, { x: 1.06, y: 1.06, duration: 0.35, ease: 'cubic-bezier(0.215,0.61,0.355,1)' });
        gsap.to(plates[i].accent.material, { emissiveIntensity: 1.4, duration: 0.35, ease: 'cubic-bezier(0.215,0.61,0.355,1)' });
        const cap = plates[i].caption;
        if (cap) {
          cap.visible = true;
          gsap.fromTo(cap.position, { x: cap.position.x - 0.3, opacity: 0 }, { x: cap.position.x, opacity: 1, duration: 0.35, ease: 'power2.out' });
        }
        // Unfocus others
        for (let j = 0; j < numPlates; j++) {
          if (j !== i && plates[j].focused) {
            plates[j].focused = false;
            gsap.to(plates[j].plate.scale, { x: 1.0, y: 1.0, duration: 0.35, ease: 'cubic-bezier(0.215,0.61,0.355,1)' });
            gsap.to(plates[j].accent.material, { emissiveIntensity: 0, duration: 0.35, ease: 'cubic-bezier(0.215,0.61,0.355,1)' });
            const cap2 = plates[j].caption;
            if (cap2) {
              gsap.to(cap2.position, { opacity: 0, duration: 0.2, onComplete: () => { cap2.visible = false; } });
            }
          }
        }
      }
    }
  }

  function scrollTick() {
    const dt = 0.016;
    scrollState.velocity *= (1 - 0.12);
    scrollState.currentY += scrollState.velocity * dt;
    scrollState.currentY = ((scrollState.currentY % loopHeight) + loopHeight) % loopHeight;
    updatePlates(scrollState.currentY);

    // Fly-through depth offset
    const depthProg = (scrollState.currentY / loopHeight) * 2 - 1;
    group.userData.cameraDepthOffset = depthProg * 2.5 * 0.5;
    ctx.emit('camera-depth-offset', { offset: group.userData.cameraDepthOffset });

    if (Math.abs(scrollState.velocity) > 0.001) {
      scrollState.animId = requestAnimationFrame(scrollTick);
    } else {
      // Weighted settle
      const tl = gsap.to(scrollState, {
        velocity: 0,
        duration: 0.9,
        ease: 'power4.out',
        onUpdate: () => {
          scrollState.currentY += scrollState.velocity * 0.016;
          scrollState.currentY = ((scrollState.currentY % loopHeight) + loopHeight) % loopHeight;
          updatePlates(scrollState.currentY);
        }
      });
      timelines.push(tl);
    }
  }

  group.userData.handlers = {
    scroll: (e) => {
      if (e.deltaY) {
        scrollState.velocity += e.deltaY * 0.01 * 1.5;
        scrollState.velocity = Math.max(-3, Math.min(3, scrollState.velocity));
        if (scrollState.animId) cancelAnimationFrame(scrollState.animId);
        scrollState.animId = requestAnimationFrame(scrollTick);
      }
    }
  };

  // Initialize
  updatePlates(0);

  // --- Lights ---
  const key = new ctx.THREE.DirectionalLight(colors.paper || '#e8ecf2', 1.2);
  key.position.set(2, 3, 4);
  group.add(key);
  const rim = new ctx.THREE.DirectionalLight(colors.accent || '#ff2a38', 0.8);
  rim.position.set(-3, 2, -1);
  group.add(rim);
  const fill = new ctx.THREE.AmbientLight(0x222233, 0.6); // slight warm fill
  group.add(fill);

  // Contact shadow plane
  const shadowGeo = new PlaneGeometry(3.5, 0.8);
  const shadowMat = new MeshBasicNodeMaterial({
    transparent: true,
    depthWrite: false
  });
  const shadowFn = Fn(() => {
    const vUv = uv();
    const alpha = smoothstep(0.4, 0.0, length(vUv.sub(0.5).mul(vec2(1.0, 0.5)))).mul(0.5);
    return vec4(0.0, 0.0, 0.0, alpha);
  });
  shadowMat.colorNode = shadowFn();
  const shadow = new Mesh(shadowGeo, shadowMat);
  shadow.position.set(colX, -3.2, -0.1);
  shadow.rotation.x = -Math.PI / 2;
  group.add(shadow);

  // --- Cinematic primitives ---
  for (const prim of (config.cinematicPrimitives || [])) {
    if (prim.name === 'fly-through') {
      const result = ctx.primitives['fly-through'](group, {
        depthUnits: 2.5,
        scrollRange: loopHeight,
        scrollState: scrollState
      });
      if (result) {
        cleanups.push(result.cleanup);
        if (result.timeline) timelines.push(result.timeline);
      }
    }
  }

  // --- Cleanup ---
  group.userData.cleanup = () => {
    timelines.forEach(tl => tl.kill());
    if (scrollState.animId) cancelAnimationFrame(scrollState.animId);
    cleanups.forEach(fn => fn());
    backGeo.dispose(); backMat.dispose();
    group.traverse(child => {
      if (child.isMesh) {
        child.geometry?.dispose();
        child.material?.dispose();
      }
    });
  };

  return group;
}
